BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('ab423a81-3a01-53c6-bab8-c303f8a7f9f5', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'JOptionPane.showInputDialog retorna normalmente:', '["Um JButton.","Um double automaticamente.","Um int automaticamente.","Uma exceção sempre.","Texto como String."]'::jsonb, 4, 'Entrada numérica exige análise posterior do texto.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.3, páginas 411–412 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f6e5aa2b-6796-5bb5-916a-a53cd89e7c27', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Cancelar showInputDialog pode retornar:', '["null.","Sempre \"0\".","Um int negativo.","Um JFrame novo.","Sempre String vazia."]'::jsonb, 0, 'O programa precisa distinguir cancelamento e entrada fornecida.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.3, páginas 411–412 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a675a360-08db-59f9-9e76-ab971583b414', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Swing pertence principalmente ao pacote:', '["java.sql.","java.net apenas.","javax.swing.","java.time.","java.nio.file."]'::jsonb, 2, 'Muitos componentes gráficos Swing estão nesse pacote.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.4, páginas 413 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('10b1c027-6277-5b0e-946f-02f51768d402', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'JFrame representa principalmente:', '["Uma lista genérica.","Um gerador aleatório.","Uma janela de nível superior.","Um campo de senha.","Um arquivo."]'::jsonb, 2, 'A janela pode conter painéis e outros componentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.5, páginas 414–417 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5c187206-6054-5a0f-871f-bf492323ab84', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'JLabel é usado principalmente para:', '["Gerenciar threads.","Receber qualquer texto editável por padrão.","Ler arquivos binários.","Exibir texto ou imagem.","Executar SQL."]'::jsonb, 3, 'Rótulos apresentam informação, sem serem editores de texto comuns.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.5, páginas 414–417 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f47a1c5a-c879-52af-8392-208dbf599841', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'JTextField é adequado principalmente para:', '["Uma janela de nível superior.","Uma tabela relacional.","Texto multilinha com parágrafos por definição.","Entrada de texto em uma linha.","Desenho vetorial."]'::jsonb, 3, 'JTextArea atende ao caso de edição textual multilinha.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.6, páginas 418–422 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6bcf1938-022b-537c-a57c-4f859f97120a', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'JPasswordField fornece para senhas uma interface que:', '["Criptografa automaticamente o banco.","Mascara visualmente os caracteres digitados.","Elimina o valor da memória imediatamente.","Substitui autenticação.","Garante segurança de toda aplicação."]'::jsonb, 1, 'Mascaramento visual não equivale a uma política completa de segurança.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.6, páginas 418–422 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('924bfc96-7df0-5de9-81fe-ade63e01ed17', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'O tratamento de eventos normalmente liga:', '["Um array a uma classe abstrata.","Um construtor a um import.","Uma fonte de eventos a um ouvinte registrado.","Somente um arquivo a um pacote.","Uma senha a um índice."]'::jsonb, 2, 'O ouvinte executa o comportamento associado ao evento.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.7, páginas 423 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('602ed37d-55a5-536a-a243-8ed39abfe2c3', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Registrar ActionListener em um botão permite reagir a:', '["A coleta de lixo.","Qualquer consulta SQL.","Somente movimentos do mouse.","Eventos de ação do botão.","Somente eventos de janela fechada."]'::jsonb, 3, 'O tipo do ouvinte deve ser compatível com o evento.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.8, páginas 424 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4db1f813-09d4-5515-8406-6fa9ec10d117', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Qual método integra o contrato de ActionListener?', '["paintComponent.","keyTyped.","mouseDragged.","actionPerformed.","windowOpened."]'::jsonb, 3, 'A assinatura recebe o evento de ação correspondente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.9, páginas 425–427 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('122076b1-d132-5629-829c-a102d31380c0', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'JCheckBox é apropriado para:', '["Opções de seleção independentes.","Um arquivo serializado.","Exclusão mútua obrigatória sem agrupamento.","Uma tabela hash.","Uma área de texto."]'::jsonb, 0, 'Várias caixas podem permanecer selecionadas simultaneamente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.10, páginas 428–432 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9a5612c0-42fe-5f3d-b3dc-91c6eb347139', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'Para exclusão mútua entre JRadioButtons, usa-se tipicamente:', '["StringBuilder.","JTextArea.","Scanner.","ArrayList como garantia automática.","ButtonGroup."]'::jsonb, 4, 'O agrupamento coordena o estado de seleção dos botões.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.10, páginas 428–432 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4c273980-82a2-51e6-8299-95bdeb86b42e', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'JComboBox apresenta principalmente:', '["Uma pilha.","Uma árvore de arquivos obrigatória.","Uma janela de console.","Um gráfico vetorial.","Uma seleção entre itens de uma lista compacta."]'::jsonb, 4, 'O componente combina uma lista de escolhas e a apresentação da seleção.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.11, páginas 433–435 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3d0c8074-db86-5f35-9d73-be7d6784dc8c', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'JList é usada para:', '["Representar somente um rótulo.","Executar transações.","Exibir e selecionar itens de uma lista.","Criar threads.","Capturar senhas em disco."]'::jsonb, 2, 'Seu modelo e modo de seleção definem os dados e escolhas permitidas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.12, páginas 436–437 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c0f4a56a-083a-51c5-a645-3875f9c991b2', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Permitir vários itens selecionados em JList exige:', '["Usar sempre um JFrame por item.","Configuração de modo de seleção compatível.","Remover o modelo de dados.","Impedir qualquer evento.","Transformar itens em int."]'::jsonb, 1, 'A seleção múltipla é uma capacidade configurável do componente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.13, páginas 438–439 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8e8e009e-f3e1-5142-8ce1-2bbdfc84cc51', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'Uma classe adaptadora de eventos facilita:', '["Implementar apenas os métodos de interesse entre os fornecidos vazios.","Transformar todo evento em clique.","Eliminar interfaces.","Executar no lugar do sistema operacional.","Dispensar registro de ouvintes sempre."]'::jsonb, 0, 'Adaptadores evitam escrever todos os métodos de certas interfaces extensas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.15, páginas 443–445 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a72d6134-8756-5c64-bc74-c793648a1743', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Qual interface é associada a movimentos e arraste do mouse?', '["Serializable.","Runnable.","WindowListener apenas.","ActionListener apenas.","MouseMotionListener."]'::jsonb, 4, 'Ela distingue movimento simples e arraste.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.14, páginas 440–442 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ec059a7b-4d88-5da9-93ad-29a55c0d95f0', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Um gerenciador de layout tem como responsabilidade principal:', '["Executar métodos main.","Organizar posição e tamanho dos componentes.","Compilar classes.","Validar senhas.","Persistir objetos."]'::jsonb, 1, 'Layouts evitam depender apenas de coordenadas absolutas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.18, páginas 451–458 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7066f6b5-fb6a-58ef-bd4b-b050300cbd32', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'BorderLayout organiza componentes em regiões como:', '["NORTH, SOUTH, EAST, WEST e CENTER.","BEGIN e END.","READ e WRITE.","HEAD e TAIL apenas.","PUBLIC e PRIVATE."]'::jsonb, 0, 'As cinco regiões participam do arranjo do contêiner.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.18, páginas 451–458 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fc659dad-04e8-5a99-9151-b37cbaa1def2', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Para texto editável multilinha em Swing, usa-se tipicamente:', '["JPasswordField apenas.","JTextArea.","JRadioButton.","JLabel apenas.","JButton."]'::jsonb, 1, 'Pode-se combinar a área com JScrollPane para rolagem.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 12, seção 12.20, páginas 460–462 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
